package mvt

import (
	"strings"
	"testing"
)

// The fixtures below are the message examples from OAG's freely published
// "MVT / MVA / DIV Aircraft Movement Messages: Data Elements and Message
// Examples", copied by hand, character for character. They are external
// artefacts on purpose: a fixture generated by this package's own builder
// would prove nothing, which is the trap this repository has fallen into
// twice before.

func TestParseDepartureExample(t *testing.T) {
	// Departure message, four-digit time form, from the OAG examples.
	m, err := Parse("MVT\nSD200/21.PMDFG.CDG\nAD1100/1115 EA1500 FRA\nDL72/0015\nPX112\nSI DEICING")
	if err != nil {
		t.Fatalf("Parse: %v", err)
	}
	if m.Kind != KindMVT || m.Flight != "SD200" || m.Day != "21" ||
		m.Registration != "PMDFG" || m.Station != "CDG" {
		t.Fatalf("identification read wrong: %+v", m)
	}
	if m.AD == nil || m.AD.First != "1100" || m.AD.Second != "1115" {
		t.Errorf("AD = %+v, want 1100/1115", m.AD)
	}
	if m.EA == nil || m.EA.Time != "1500" || m.EA.Airport != "FRA" {
		t.Errorf("EA = %+v, want 1500 FRA", m.EA)
	}
	if len(m.Delays) != 1 || m.Delays[0] != (Delay{Code: "72", Duration: "0015"}) {
		t.Errorf("Delays = %+v, want [72/0015]", m.Delays)
	}
	if len(m.Pax) != 1 || m.Pax[0] != 112 {
		t.Errorf("Pax = %v, want [112]", m.Pax)
	}
	if m.SI != "DEICING" {
		t.Errorf("SI = %q, want DEICING", m.SI)
	}
	if len(m.Unrecognised) != 0 {
		t.Errorf("nothing in this example should be unrecognised: %v", m.Unrecognised)
	}
}

func TestParseDepartureSixDigitForm(t *testing.T) {
	// The same departure in the six-digit UTC date-and-time form.
	m, err := Parse("MVT\nSD200/21.PMDFG.CDG\nAD211100/211115 EA1500 FRA\nDL72/0015\nPX112\nSI DEICING")
	if err != nil {
		t.Fatalf("Parse: %v", err)
	}
	if m.AD == nil || m.AD.DayA != "21" || m.AD.First != "1100" ||
		m.AD.DayB != "21" || m.AD.Second != "1115" {
		t.Errorf("AD = %+v, want 21+1100 / 21+1115", m.AD)
	}
}

func TestParseArrivalExample(t *testing.T) {
	m, err := Parse("MVT\nSD200/22.PMDFG.FRA\nAA1515/1520\nFLD22")
	if err != nil {
		t.Fatalf("Parse: %v", err)
	}
	if m.Station != "FRA" {
		t.Errorf("an arrival message carries the arrival airport; got %q", m.Station)
	}
	if m.AA == nil || m.AA.First != "1515" || m.AA.Second != "1520" {
		t.Errorf("AA = %+v, want 1515/1520", m.AA)
	}
	if m.FLD != "22" {
		t.Errorf("FLD = %q, want 22", m.FLD)
	}
}

