func TestParseDelayedTakeOffExample(t *testing.T) {
	m, err := Parse("MVT\nSD200/22.PMDFG.CDG\nAD221115 EO1135 EA1530 FRA\nDL72/0025\nEB1545")
	if err != nil {
		t.Fatalf("Parse: %v", err)
	}
	if m.AD == nil || m.AD.DayA != "22" || m.AD.First != "1115" || m.AD.Second != "" {
		t.Errorf("AD = %+v, want 22+1115 with no airborne time", m.AD)
	}
	if m.EO != "1135" || m.EB != "1545" {
		t.Errorf("EO/EB = %q/%q, want 1135/1545", m.EO, m.EB)
	}
	if m.EA == nil || m.EA.Time != "1530" || m.EA.Airport != "FRA" {
		t.Errorf("EA = %+v", m.EA)
	}
}

